files.content:
/* The box reads as one field: control tokens for the frame, focus ring on
 * :focus-within since the real input inside is borderless. */
.taginput {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1);
  min-block-size: var(--control-height);
  padding-inline: var(--space-2);
  /* 2px, NOT 4. The tag inside stands at --control-height-sm (32); at 4px of
   * padding the content box is 40 and the borders take it to 42, so the field
   * pushed past its own floor and stood 2px taller than every other control in
   * the row (measured 2026-08-29). At 2px the content is 38, the 40 floor wins,
   * and a tag that wraps to a second line still grows the field the way it
   * should. */
  padding-block: var(--space-2xs);
  border: 1px solid var(--input);
  border-radius: var(--control-radius);
  background: var(--background);
  transition: border-color var(--duration-fast);
}
.taginput:hover:not([data-disabled]) { border-color: var(--ring); }
.taginput[data-invalid]:focus-within { outline-color: var(--destructive); }
.taginput:focus-within {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}
.taginput[data-invalid] { border-color: var(--destructive); }
.taginput[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

.taginput-field {
  flex: 1;
  min-inline-size: 6ch;
  border: none;
  outline: none; /* the frame's :focus-within ring is the visible focus */
  background: transparent;
  color: var(--foreground);
  font: inherit;
  padding: 0;
}
.taginput-field::placeholder { color: var(--muted-foreground); }

import './TagInput.css'
import { useState, type KeyboardEvent } from 'react'
import { cn } from '../lib/cn'
import { Chip } from '../Chip'

type Props = {
  /** The committed tags, in order. */
  value: string[]
  onChange: (value: string[]) => void
  /** Accessible name for the text field. */
  label: string
  placeholder?: string
  /** A STATE, not a style: it turns the border and hands <Field> the hook it needs to read the
   *  error out as part of the field.
   */
  invalid?: boolean
  /** Dims the field and its tags together; existing tags stop offering their remove button. */
  disabled?: boolean
  className?: string
}

/* Free-text tags: type, press Enter or comma, get a removable <Chip> token. For
 * choosing from a KNOWN option list use <Combobox multiple>; this one is for
 * values the user invents (emails, labels, keywords). Duplicates are dropped
 * case-insensitively, blur commits what was typed, and Backspace in the empty
 * field removes the last tag. 
   *
   * Copy: the placeholder says how to add one — "Type and press Enter" — because a
   * field that accepts many values does not look like one that does.
   */
export function TagInput({ value, onChange, label, placeholder, invalid, disabled, className }: Props) {
  const [draft, setDraft] = useState('')

  const commit = () => {
    const tag = draft.trim()
    if (!tag) return
    if (!value.some((t) => t.toLowerCase() === tag.toLowerCase())) onChange([...value, tag])
    setDraft('')
  }

  const onKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault()
      commit()
    } else if (e.key === 'Backspace' && draft === '' && value.length > 0) {
      onChange(value.slice(0, -1))
    }
  }

  return (
    <div className={cn('taginput', className)} data-invalid={invalid || undefined} data-disabled={disabled || undefined}>
      {value.map((tag) => (
        <Chip
          key={tag}
          size="sm"
          onRemove={disabled ? undefined : () => onChange(value.filter((t) => t !== tag))}
          removeLabel={`Remove ${tag}`}
        >
          {tag}
        </Chip>
      ))}
      <input
        className="taginput-field"
        value={draft}
        placeholder={value.length === 0 ? placeholder : undefined}
        disabled={disabled}
        aria-label={label}
        aria-invalid={invalid || undefined}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={onKeyDown}
        onBlur={commit}
      />
    </div>
  )
}
